INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Gantt-Diagramm ein Standardwerkzeug im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Nein", "correct": false, "because": "Es ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Gantt-Diagramm?', 3, '[{"text": "Zeitliche Abfolge von Aktivitäten darstellen", "correct": true, "because": "Fördert Planung"}, {"text": "Team direkt koordinieren", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Kosten sofort kalkulieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Gantt-Diagramm zeigt Zeitspannen. b) Es wird nur im Abschluss genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält ein Gantt-Diagramm?', 4, '[{"text": "Aktivitäten", "correct": true, "because": "Darstellen Aufgaben"}, {"text": "Unklare Zeitangaben", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Zeitbalken", "correct": true, "because": "Zeigen Dauer"}, {"text": "Meilensteine", "correct": true, "because": "Markieren Ereignisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Gantt-Diagramm geplant werden?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Methoden möglich"}, {"text": "Nein", "correct": false, "because": "Werkzeug optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase nutzt das Gantt-Diagramm primär?', 3, '[{"text": "Planung", "correct": true, "because": "Erstellt Zeitplan"}, {"text": "Initiierung", "correct": false, "because": "Ziele werden gesetzt"}, {"text": "Abschluss", "correct": false, "because": "Projekt wird beendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Gantt-Diagramm nur für große Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Gantt-Diagramm im Controlling?', 3, '[{"text": "Fortschritt gegenüber Plan überwachen", "correct": true, "because": "Vergleicht Ist-Soll"}, {"text": "Team direkt einteilen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Ergebnisse präsentieren", "correct": false, "because": "Abschlussaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Gantt-Diagramm zeigt Abhängigkeiten. b) Es ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Gantt-Diagramm?', 3, '[{"text": "Zeitplanung wird schwieriger", "correct": true, "because": "Fehlende Visualisierung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Unklarheit möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Gantt-Diagramm ohne Zeitangaben erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Zeit ist Kern"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt einen Gantt-Diagramm-Eintrag?', 3, '[{"text": "Testphase: 1.6.–15.6.", "correct": true, "because": "Klar mit Zeitbalken"}, {"text": "Irgendwas testen", "correct": false, "because": "Zu vage"}, {"text": "Team soll testen", "correct": false, "because": "Keine Zeitangabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Gantt-Diagramm nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Zeitplan"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Gantt-Diagramm?', 4, '[{"text": "Aktivitätsbalken", "correct": true, "because": "Zeigen Dauer"}, {"text": "Unklare Zeitpunkte", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Meilensteine", "correct": true, "because": "Markieren Ereignisse"}, {"text": "Zeitachse", "correct": true, "because": "Definiert Zeitraum"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Gantt-Diagramm dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt das Gantt-Diagramm?', 3, '[{"text": "Excel für Balkendiagramme", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Keine Software", "correct": false, "because": "Fehlt Struktur"}, {"text": "Zufällige Skizzen", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Gantt-Diagramm ohne Arbeitspakete erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Aufgabenbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Erstellung eines Gantt-Diagramms?', 3, '[{"text": "Unklare Aktivitätsdauern", "correct": true, "because": "Verhindern Planung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Erstellung"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Gantt-Diagramm hilft bei der Fortschrittskontrolle. b) Es zeigt nur Meilensteine.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Gantt-Diagramms?', 3, '[{"text": "Klare Zeitübersicht", "correct": true, "because": "Fördert Steuerung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Planung", "correct": false, "because": "Fördert Struktur"}]');
